{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 법 제11조 제1항에 따라 설치한 자전거주차장의 원칙적 무료 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 자전거이용 활성화에 관한 조례 제9조 제1항 본문에 따르면, 법 제11조 제1항에 따라 설치된 자전거주차장의 주차요금은 무료로 한다.",
          "b_ids": "자전거:제9조제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "민간단체 위탁 등 특별한 사유로 요금을 받을 때 별표가 정한 1시간·1일·월정기 요금 범위",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "자전거주차장의 관리·운영을 자전거이용민간단체 등에 위탁하는 등 특별한 사유가 있는 경우에는 주차요금을 별표의 범위 내에서 규칙으로 정하여 부과할 수 있다.",
          "b_ids": "자전거:제9조제1항단서"
        },
        {
          "a_text": "별표에 따른 주차요금 범위는 1회주차시(1시간당) 200원, 1일주차권 1,000원, 월 정기권 15,000원이다(단위: 원/구획).",
          "b_ids": "자전거:별표#행1, 자전거:별표#보충단위"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
